    {
        float4x4 m = float4x4(0.0);
        float amzp_angle = (fov / 180.0) * PI;
        float f = 1. / tan( amzp_angle * 0.5 );
        m[0][0] = f / aspect;
        m[1][1] = f;
        m[2][2] = (far + near) / (near - far);
        m[2][3] = -1.;
        m[3][2] = (2. * far*near) / (near - far);
        return m;
    }
    float4x4 CamControl( float3 eye, float pitch)
    {
        float cosPitch = cos(pitch);
        float sinPitch = sin(pitch);
        float3 xaxis = float3( 1, 0, 0. );
        float3 yaxis = float3( 0., cosPitch, sinPitch );
        float3 zaxis = float3( 0., -sinPitch, cosPitch );
        float4x4 viewMatrix = float4x4(
            float4( xaxis.x, yaxis.x, zaxis.x, 0 ),
            float4( xaxis.y, yaxis.y, zaxis.y, 0 ),
            float4( xaxis.z, yaxis.z, zaxis.z, 0 ),
            float4( -dot( xaxis, eye ), -dot( yaxis, eye ), -dot( zaxis, eye ), 1 )
        );
        return viewMatrix;
    }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 syamjaidtz;
        syamjaidtz = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        syamjaidtz.y*=layer.y/layer.x;
        syamjaidtz /= amzp_scale;
        syamjaidtz *= rot2m((-180.0+amzp_angle)*0.0174533);
        syamjaidtz += float2((-250.0), (200.0))*float2(-1.,1.)/500.;
     float4 fragColor;
     float2 uv = syamjaidtz;
        float2 p = 2.*uv-1.;
     p.x *= screen.zw.x/screen.zw.y;
     float3 eye = float3(0., 0.25+0.25*cos(0.5*amzp_progressa), -1.);
        float4x4 projmat = CreatePerspectiveMatrix(50., screen.zw.x/screen.zw.y, 0.1, 10.);
        float4x4 viewmat = CamControl(eye, -5.*PI/180.);
        float4x4 vpmat = viewmat*projmat;
     float3 col = float3(0.);
     float3 acc = float3(0.);
     float d;
        float4 amzLocal_pos = float4(0.);
     float lh = -screen.zw.y;
     float off = 0.1*amzp_progressb;
     float h = 0.;
     float z = 0.1;
     float zi = 0.05;
     for (float i=0.0; i<(amzp_AMOUNT); ++i)
     {
            amzLocal_pos = float4(p.x, 0.5*fbm4(0.5*float2(eye.x+p.x, z+off)), eye.z+z, 1.);
            h = (vpmat*amzLocal_pos).y - p.y;
      if (h>lh)
      {
       d = abs(h);
       col = float3( d<0.005?smoothstep(1.,0.,d*192.):0. );
       col *= exp(-0.1*float(i));
                acc += col;
       lh = h;
      }
      z += zi;
     }
     col = sqrt(clamp(acc, 0., 1.));
     float3 bkg = float3(0.0,0.0,0.0);
     float2 r = -1.0 + 2.0*(uv);
     float vb = max(abs(r.x), abs(r.y));
     col *= (0.15 + 0.85*(1.0-exp(-(1.0-vb)*30.0)));
     fragColor = float4(col,1.0);
         const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float4 gradmap;
            float luminance = dot(fragColor.rgb, luminanceWeighting);
            gradmap = mix(amzp_color1,amzp_color2,luminance)*fragColor.a;
         float4 factor = mix(texColorX,gradmap,amzp_alpha);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_bright) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= amzp_bright;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            factor *= amzp_bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = resultfinal;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

